<script setup>
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { message, Modal } from 'ant-design-vue'
import { useRos } from '../composables/useRos'
const { state, HOST } = useRos()
const SRC = [['all','全部'],['sys','systemd'],['ros','/rosout']], LVL = [['all','全部'],['error','错误'],['warn','警告'],['info','信息']]
const srcF=ref('all'), lvlF=ref('all'), svcF=ref('all'), q=ref(''), paused=ref(false), follow=ref(true), box=ref(null), busy=ref({})
const desktop=ref(null), desktopBusy=ref(false), navigationStack=ref(null), navigationBusy=ref(false)
const cachedUnits = ref(null)
const hhmmss=t=>(String(t||'').match(/\d{2}:\d{2}:\d{2}/)||['--:--:--'])[0], dur=t=>t==null?'--':t>=86400?`${Math.floor(t/86400)}天`:t>=3600?`${Math.floor(t/3600)}时`:`${Math.floor(t/60)}分`
const RESPONSIBILITIES={
 start_app_node:{summary:'启动并托管关键硬件和基础 ROS 节点。',items:['RGB / 深度相机驱动','雷达驱动与过滤','底盘控制器、里程计、IMU','机械臂舵机控制','ROS 基础组件','rosbridge :9090 与 MJPEG :8080']},
 webctl:{summary:'提供机器人网页控制台与受限运维 API。',items:['网页服务 :8000','系统诊断与动作组 API','固定白名单内的服务管理']},
 'jetson-agent':{summary:'采集 Jetson 状态并发布运维数据。',items:['CPU / GPU / 内存与功耗','服务状态和运行日志','硬件与网络快照']},
 'snack-butler':{summary:'负责视觉识别、三维定位与安全抓取。',items:['YOLO / 深度定位','IK 可达性与抓取决策','机械臂状态机与标注图']},
 'webrtc-agent':{summary:'将相机图像低延迟传给浏览器。',items:['WebRTC 信令 :8091','浏览器视频会话','视频流回退协同']},
 'explorer-agent':{summary:'负责自主探索任务与返航策略。',items:['Frontier 目标选择','探索任务状态','通过 Nav2 请求移动']},
 'exploration-nav':{summary:'提供在线建图、定位与路径规划。',items:['SLAM Toolbox','Nav2 规划与避障','地图和路径话题']},
 'nav-safety':{summary:'所有导航速度的安全闸门。',items:['雷达距离限速','近障急停','无雷达保守降级']},
 'lidar-watchdog':{summary:'检测并恢复雷达断连。',items:['USB 雷达状态监测','基础 bringup 恢复','不直接发送底盘速度']},
 'llm-agent':{summary:'把自然语言转为受限机器人指令。',items:['自然语言 HTTP :8092','命令参数限幅','调用安全接口']},
}
const responsibility=n=>RESPONSIBILITIES[n]||{summary:'机器人自建工作负载。',items:['由 systemd 常驻守护','可在白名单内管理']}
let frozen=[]
const units=computed(()=>state.units?.services?.length ? state.units.services : cachedUnits.value?.services||[]), activeN=computed(()=>units.value.filter(s=>s.state==='active').length), usedMem=computed(()=>units.value.reduce((n,s)=>n+(+s.mem_mb||0),0))
const bootstrapRows=computed(()=>units.value.map(s=>({t:new Date().toISOString(),from:'sys',unit:s.name,src:'service-monitor',lvl:s.state==='active'?'info':'warn',msg:`[startup] ${s.state}/${s.sub||'--'} pid=${s.pid||'--'} uptime=${dur(s.uptime)} mem=${s.mem_mb??'--'}MB`})))
const rows=computed(()=>{const all=paused.value?frozen:(state.logs.length?state.logs:bootstrapRows.value),kw=q.value.trim().toLowerCase();return all.filter(e=>(srcF.value==='all'||e.from===srcF.value)&&(lvlF.value==='all'||e.lvl===lvlF.value)&&(svcF.value==='all'||e.unit===svcF.value||e.src===svcF.value)&&(!kw||(e.msg+' '+(e.src||'')).toLowerCase().includes(kw)))})
const serviceOptions=computed(()=>[{value:'all',label:'全部工作负载'},...units.value.map(s=>({value:s.name,label:`${s.name} · ${s.desc}`}))]), counts=computed(()=>state.logs.reduce((c,e)=>{if(e.lvl in c)c[e.lvl]++;return c},{error:0,warn:0}))
const serviceCommand=(n,a)=>`sudo systemctl ${a} ${n}.service`, desktopCommand=e=>`sudo /home/ubuntu/${e?'enable_desktop.sh':'disable_desktop.sh'}`, navigationCommand=r=>`sudo /home/ubuntu/${r?'resume_navigation_stack.sh':'pause_navigation_stack.sh'}`
async function copyCommand(c){try{await navigator.clipboard.writeText(c)}catch(_){const e=document.createElement('textarea');e.value=c;e.style.cssText='position:fixed;opacity:0';document.body.appendChild(e);e.select();document.execCommand('copy');e.remove()}message.success('命令已复制')}
async function refreshModes(){const get=async(p,t)=>{try{const r=await fetch(`http://${HOST}:8000${p}`,{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||r.status);t.value=d}catch(e){t.value={error:e.message}}};await Promise.all([get('/api/system/desktop',desktop),get('/api/system/navigation-stack',navigationStack)])}
function loadCachedUnits(){try{const raw=sessionStorage.getItem('jetrover:services');if(raw){const data=JSON.parse(raw);if(data?.services?.length)cachedUnits.value=data}}catch(_){}}
async function refreshUnits(){try{const r=await fetch(`http://${HOST}:8000/api/services`,{cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.error||r.status);if(data.services?.length){cachedUnits.value=data;sessionStorage.setItem('jetrover:services',JSON.stringify(data))}}catch(_){/* ROS 上报仍是兜底，保留最近有效快照 */}}
async function put(p,t,b,ok){b.value=true;try{const r=await fetch(`http://${HOST}:8000${p}`,{method:'PUT'}),d=await r.json();if(!r.ok)throw Error(d.error||r.status);t.value=d;message.success(ok)}catch(e){message.error('操作失败：'+e.message);throw e}finally{b.value=false}}
function toggleDesktop(e){Modal.confirm({title:e?'开启图形桌面？':'关闭图形桌面？',content:e?'会恢复 7 英寸触摸屏桌面。':'会立即停止 GNOME，后续无桌面启动；网页、SSH、ROS 与控制不会停止。',okText:e?'开启':'关闭',cancelText:'取消',okButtonProps:e?{}:{danger:true},onOk:()=>put(`/api/system/desktop/${e?'enable':'disable'}`,desktop,desktopBusy,e?'图形桌面已开启':'图形桌面已关闭')})}
function toggleNavigation(r){Modal.confirm({title:r?'恢复自主导航？':'进入导航待机？',content:r?'会恢复 SLAM、Nav2 和自主探索。':'会暂停 SLAM、Nav2 与自主探索，约释放 1 GB 内存；相机、抓取、雷达看门狗和速度安全闸门继续运行。',okText:r?'恢复':'待机',cancelText:'取消',okButtonProps:r?{}:{danger:true},onOk:()=>put(`/api/system/navigation-stack/${r?'resume':'pause'}`,navigationStack,navigationBusy,r?'自主导航已恢复':'导航已进入待机')})}
function serviceAction(s,a){const core=s.name==='start_app_node',nav=['explorer-agent','exploration-nav','nav-safety'].includes(s.name),stop=a==='stop';Modal.confirm({title:`${stop?'停止':'重启'} ${s.name}？`,okText:`确认${stop?'停止':'重启'}`,cancelText:'取消',content:stop?'服务会保持离线，直到手动重启；确认不会影响正在执行的任务。':core?'会重建 ROS、相机和底层驱动话题；不会向机械臂或底盘发送动作命令。':nav?'该服务参与自主移动，请确认小车已停稳。':'服务会短暂离线，通常数秒内恢复。',okButtonProps:{danger:stop||core||nav},async onOk(){busy.value[`${s.name}:${a}`]=true;try{const r=await fetch(`http://${HOST}:8000/api/services/${s.name}/${a}`,{method:'POST'}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||`HTTP ${r.status}`);message.success(`${s.name} 正在${stop?'停止':'重启'}`)}catch(e){message.error(`${stop?'停止':'重启'}失败：${e.message}`);throw e}finally{busy.value[`${s.name}:${a}`]=false}}})}
const restart=s=>serviceAction(s,'restart'),stop=s=>serviceAction(s,'stop')
watch(paused,v=>{frozen=v?state.logs.slice():[]});watch(()=>state.logs.length,()=>{if(!paused.value&&follow.value)nextTick(()=>{if(box.value)box.value.scrollTop=box.value.scrollHeight})})
function onScroll(){if(box.value)follow.value=box.value.scrollHeight-box.value.scrollTop-box.value.clientHeight<40}function clear(){state.logs.splice(0);frozen=[]}function toBottom(){follow.value=true;if(box.value)box.value.scrollTop=box.value.scrollHeight}onMounted(()=>{loadCachedUnits();refreshModes();refreshUnits()})
</script>

<template>
 <div class="ops-page">
  <section class="ops-bar">
   <div class="cluster-state"><i/>{{activeN}}/{{units.length}} <span>· {{usedMem.toFixed(0)}} MB</span></div>
   <div class="mode-strip">
    <a-popover trigger="hover" placement="bottom" overlay-class-name="action-pop"><template #content><b>图形桌面</b><code>{{desktopCommand(!desktop?.enabled)}}</code><button class="copy-svg" @click="copyCommand(desktopCommand(!desktop?.enabled))" aria-label="复制命令"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="10" height="11" rx="1"/><path d="M15 9V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h4"/></svg></button></template><div class="mode-chip"><span>桌面</span><b>{{desktop?.enabled?'开启':'关闭'}}</b><a-switch :checked="!!desktop?.enabled" :loading="desktopBusy" size="small" @change="toggleDesktop"/></div></a-popover>
    <a-popover trigger="hover" placement="bottom" overlay-class-name="action-pop"><template #content><b>自主导航</b><code>{{navigationCommand(!navigationStack?.running)}}</code><button class="copy-svg" @click="copyCommand(navigationCommand(!navigationStack?.running))" aria-label="复制命令"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="10" height="11" rx="1"/><path d="M15 9V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h4"/></svg></button></template><div class="mode-chip"><span>导航</span><b>{{navigationStack?.running?'运行':'待机'}}</b><a-switch :checked="!!navigationStack?.running" :loading="navigationBusy" size="small" @change="toggleNavigation"/></div></a-popover>
    <a-popover trigger="hover" placement="bottomRight" overlay-class-name="action-pop"><template #content><b>相机 / ROS 主节点</b><div class="cmd-line"><code>{{serviceCommand('start_app_node','restart')}}</code><button class="copy-svg" @click="copyCommand(serviceCommand('start_app_node','restart'))" aria-label="复制重启命令"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="10" height="11" rx="1"/><path d="M15 9V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h4"/></svg></button></div><div class="cmd-line"><code>{{serviceCommand('start_app_node','stop')}}</code><button class="copy-svg" @click="copyCommand(serviceCommand('start_app_node','stop'))" aria-label="复制停止命令"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="10" height="11" rx="1"/><path d="M15 9V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h4"/></svg></button></div></template><div class="mode-chip core"><span>底层 ROS</span><b>在线</b><button class="icon-btn" :class="{loading:busy['start_app_node:restart']}" :title="serviceCommand('start_app_node','restart')" @click="restart({name:'start_app_node'})" aria-label="重启底层"><svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 1-2.34-5.66"/><path d="M20 4v7h-7"/></svg></button><button class="icon-btn danger" :class="{loading:busy['start_app_node:stop']}" :title="serviceCommand('start_app_node','stop')" @click="stop({name:'start_app_node'})" aria-label="停止底层"><svg viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12" rx="1"/></svg></button></div></a-popover>
   </div>
  </section>
  <section class="workloads"><div class="section-title"><b>服务 / Pod</b><small>悬浮查看职责、最终命令与复制</small></div><div class="pod-grid">
   <a-popover v-for="s in units" :key="s.name" trigger="hover" placement="topLeft" overlay-class-name="pod-popover"><template #content><div><b>{{s.name}}</b><p>{{responsibility(s.name).summary}}</p><ul><li v-for="i in responsibility(s.name).items" :key="i">{{i}}</li></ul><div class="cmd-line"><code>{{serviceCommand(s.name,'restart')}}</code><button class="copy-svg" @click.stop="copyCommand(serviceCommand(s.name,'restart'))" aria-label="复制重启命令"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="10" height="11" rx="1"/><path d="M15 9V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h4"/></svg></button></div><div v-if="s.name!=='webctl'" class="cmd-line"><code>{{serviceCommand(s.name,'stop')}}</code><button class="copy-svg" @click.stop="copyCommand(serviceCommand(s.name,'stop'))" aria-label="复制停止命令"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="10" height="11" rx="1"/><path d="M15 9V5a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h4"/></svg></button></div></div></template><article :class="['pod',s.state,{selected:svcF===s.name}]" @click="svcF=svcF===s.name?'all':s.name"><header><span :class="['dot',s.state]"/><code>{{s.name}}</code><em>{{s.state==='active'?'Running':s.state}}</em></header><p>{{s.desc}}</p><dl><div><dt>PID</dt><dd>{{s.pid||'—'}}</dd></div><div><dt>内存</dt><dd>{{s.mem_mb==null?'—':`${s.mem_mb} MB`}}</dd></div><div><dt>运行</dt><dd>{{dur(s.uptime)}}</dd></div></dl><footer><span>{{s.restarts?`重启 ${s.restarts} 次`:'稳定运行'}}</span><div class="pod-actions"><button class="icon-btn" :class="{loading:busy[`${s.name}:restart`]}" :title="serviceCommand(s.name,'restart')" @click.stop="restart(s)" aria-label="重启"><svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 1-2.34-5.66"/><path d="M20 4v7h-7"/></svg></button><button v-if="s.name!=='webctl'" class="icon-btn danger" :class="{loading:busy[`${s.name}:stop`]}" :title="serviceCommand(s.name,'stop')" @click.stop="stop(s)" aria-label="停止"><svg viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12" rx="1"/></svg></button></div></footer></article></a-popover><div v-if="!units.length" class="pods-wait">正在等待 jetson-agent 上报服务清单…</div>
  </div></section>
  <a-card class="event-card" size="small" :body-style="{padding:0}"><template #title><span class="event-title">事件流 <small>{{state.logs.length}} · <b class="err">{{counts.error}} 错误</b> · <b class="warn">{{counts.warn}} 警告</b></small></span></template><div class="bar"><a-radio-group v-model:value="srcF" size="small" button-style="solid"><a-radio-button v-for="s in SRC" :key="s[0]" :value="s[0]">{{s[1]}}</a-radio-button></a-radio-group><a-radio-group v-model:value="lvlF" size="small"><a-radio-button v-for="l in LVL" :key="l[0]" :value="l[0]">{{l[1]}}</a-radio-button></a-radio-group><a-select v-model:value="svcF" size="small" :options="serviceOptions" show-search option-filter-prop="label" style="width:220px"/><a-input v-model:value="q" size="small" allow-clear placeholder="搜索事件…" style="width:170px"/><span class="sp"/><a-button size="small" :type="paused?'primary':'default'" @click="paused=!paused">{{paused?'已暂停':'暂停'}}</a-button><a-button size="small" :disabled="follow" @click="toBottom">到底部</a-button><a-button size="small" danger @click="clear">清空</a-button></div><div ref="box" class="term" @scroll="onScroll"><div v-for="(e,i) in rows" :key="i" :class="['ln',e.lvl]"><span class="t">{{hhmmss(e.t)}}</span><span :class="['tag',e.from]">{{e.from==='ros'?'ROS':'SYS'}}</span><span class="unit">{{e.unit||'ros'}}</span><span class="src">{{e.src||'-'}}</span><span class="msg">{{e.msg}}</span></div><div v-if="!rows.length" class="empty">{{state.logs.length?'没有匹配的事件':'等待日志…（systemd 与 ROS /rosout 合并）'}}</div></div></a-card>
 </div>
</template>

<style scoped>
.ops-page{max-width:1480px;margin:auto}.ops-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 2px 10px}.cluster-state{font:600 12px var(--font-code);color:var(--text-2);white-space:nowrap}.cluster-state i{display:inline-block;width:7px;height:7px;margin-right:6px;border-radius:50%;background:#34d399;box-shadow:0 0 0 3px rgba(52,211,153,.13)}.cluster-state span{color:var(--text-4);font-weight:400}.mode-strip{display:flex;gap:6px}.mode-chip{display:flex;align-items:center;gap:7px;padding:6px 8px;border:1px solid var(--divider);border-radius:7px;background:var(--surface);cursor:default}.mode-chip span{color:var(--text-4);font-size:10px}.mode-chip b{font:600 11px var(--font-code);white-space:nowrap}.mode-chip.core{gap:6px}.icon-btn{display:grid;place-items:center;width:24px;height:24px;padding:0;border:1px solid var(--divider);border-radius:5px;background:var(--surface);color:var(--text-2);cursor:pointer}.icon-btn:hover{border-color:var(--accent);color:var(--accent);background:var(--accent-soft)}.icon-btn.danger:hover{border-color:#f43f5e;color:#f43f5e;background:#fff1f2}.icon-btn svg,.copy-svg svg{width:13px;height:13px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.icon-btn.loading{opacity:.45;pointer-events:none}.workloads{padding:11px;border:1px solid var(--divider);border-radius:9px;background:var(--surface);margin-bottom:10px}.section-title{display:flex;justify-content:space-between;align-items:center;margin:0 2px 8px}.section-title b{font-size:14px}.section-title small{color:var(--text-4);font-size:10px}.pod-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(218px,1fr));gap:7px}.pod{min-width:0;border:1px solid var(--divider);border-radius:7px;padding:9px;background:var(--surface-2);cursor:pointer;transition:.14s}.pod:hover,.pod.selected{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}.pod header{display:flex;align-items:center;gap:6px}.pod code{font:600 11px var(--font-code);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pod header em{margin-left:auto;font:9px var(--font-code);color:var(--text-3)}.dot{width:6px;height:6px;border-radius:50%;background:var(--text-4);flex:0 0 auto}.dot.active{background:#34d399;box-shadow:0 0 0 3px rgba(52,211,153,.14)}.dot.failed,.dot.inactive{background:#f43f5e}.pod>p{height:25px;margin:6px 0;color:var(--text-3);font-size:10px;line-height:1.25;overflow:hidden}.pod dl{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;margin:0;padding:6px 0;border-top:1px solid var(--divider)}.pod dt{color:var(--text-4);font-size:8px}.pod dd{margin:1px 0 0;font:10px var(--font-code);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pod footer{display:flex;align-items:center;justify-content:space-between;color:var(--text-4);font-size:9px}.pod-actions{display:flex;gap:3px}.pods-wait{padding:14px;color:var(--text-3)}.event-card{margin-bottom:10px}.event-title{font-weight:600}.event-title small{font-weight:400;color:var(--text-3);margin-left:7px}.err{color:#f14c4c}.warn{color:#cca700}.bar{display:flex;flex-wrap:wrap;align-items:center;gap:7px;padding:8px 10px;border-bottom:1px solid var(--divider)}.sp{margin-left:auto}.term{height:calc(100vh - 470px);min-height:430px;overflow-y:auto;background:#1e1e1e;padding:9px 12px;font-family:var(--font-code);font-size:12px;line-height:1.55;border-radius:0 0 8px 8px}.ln{display:flex;gap:9px;white-space:pre-wrap;word-break:break-word;color:#ccc}.ln .t{color:#6a9955;flex-shrink:0}.ln .tag{flex-shrink:0;width:28px;font-size:10px}.ln .tag.sys{color:#569cd6}.ln .tag.ros{color:#c586c0}.ln .unit{color:#dcdcaa;flex-shrink:0;width:115px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ln .src{color:#9cdcfe;flex-shrink:0;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ln .msg{flex:1;min-width:0}.ln.warn .msg{color:#cca700}.ln.error .msg{color:#f14c4c}.empty{color:#808080;padding:20px 0}@media(max-width:780px){.ops-bar{align-items:flex-start;flex-direction:column}.mode-strip{width:100%;overflow-x:auto}.term{height:400px;min-height:400px}}@media(max-width:560px){.workloads{padding:8px}.pod-grid{grid-template-columns:1fr}.section-title small{display:none}.bar .sp{display:none}.bar{gap:5px}.ln .src{display:none}}
:deep(.pod-popover){max-width:330px}:deep(.pod-popover b),:deep(.action-pop b){font:600 12px var(--font-code)}:deep(.pod-popover p){margin:5px 0;color:#d4d4d8;font-size:11px}:deep(.pod-popover ul){margin:0;padding-left:16px;color:#a1a1aa;font-size:10px;line-height:1.55}:deep(.cmd-line),:deep(.action-pop code){display:flex;align-items:center;gap:6px;margin-top:7px;padding:5px 6px;border-radius:4px;background:#18181b;color:#d4d4d8;font:10px var(--font-code);word-break:break-all}:deep(.cmd-line code){padding:0;margin:0;flex:1;background:none}:deep(.action-pop code){margin:7px 0 0}.copy-svg{display:grid;place-items:center;flex:0 0 auto;width:22px;height:22px;padding:0;border:0;border-radius:4px;background:transparent;color:#a1a1aa;cursor:pointer}.copy-svg:hover{color:#fff;background:#3f3f46}
</style>
